import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import { HistorySentTime } from "@/app/(app)/history/history-sent-time";

describe("History sent time before hydration", () => {
  it("renders separate UTC date and time lines with the original timestamp", () => {
    const value = "2026-09-02T23:45:00.000Z";
    const html = renderToStaticMarkup(
      createElement(HistorySentTime, { value }),
    );
    expect(html).toContain(value);
    const lines = [...html.matchAll(/<span\b[^>]*>(.*?)<\/span>/g)].map(
      (match) => match[1],
    );
    expect(lines).toEqual(["2026-09-02", "23:45 UTC"]);
  });

  it("preserves the missing-date placeholder", () => {
    expect(
      renderToStaticMarkup(createElement(HistorySentTime, { value: null })),
    ).toBe("<span>—</span>");
  });
});
